    lines.push('| Value | Count |');
    lines.push('|---|---:|');
    for (const [k, v] of Object.entries(obj).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))) lines.push(`| \`${k}\` | ${v} |`);
    lines.push('');
